def sieve(max):
    primes = []
    for n in range(2, max + 1):
        if all(n % p != 0 for p in primes):
            primes.append(n)
    return primes

def wrap(text, cols):
    lines = []
    while len(text) > cols:
        end = text.rfind(' ', 0, cols + 1)
        if end <= 0:
            end = cols
        line, text = text[:end], text[end:]
        lines.append(line)
    if text:
        lines.append(text)
    return lines

