import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        N, M = map(int, input().split())
        A = list(map(int, input().split()))
        B = list(map(int, input().split()))

        def check(x):
            anum = 0
            for i in A:
                if i <= x:
                    anum += 1
            bnum = 0
            for i in B:
                if i >= x:
                    bnum += 1
            return True if anum >= bnum else False
        Le = 0
        Ri = 1000000001
        while abs(Le - Ri) > 1:
            mid = (Le + Ri) // 2
            flag = check(mid)
            if flag:
                Ri = mid
            else:
                Le = mid
        print(Ri)
    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()
